@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --bg-void: #070A0F;
    --surface-1: #0E1420;
    --surface-2: #162032;
    --text-primary: #F1F5F9;
    --text-secondary: #94A3B8;
  }

  /* Accessible High Contrast Themes */
  body.theme-obsidian {
    --bg-void: #070A0F;
    --surface-1: #0E1420;
    --surface-2: #162032;
    background-color: var(--bg-void);
    color: #F1F5F9;
  }

  body.theme-oled {
    --bg-void: #000000;
    --surface-1: #080808;
    --surface-2: #121212;
    background-color: #000000;
    color: #FFFFFF;
  }

  body.theme-yellow {
    --bg-void: #000000;
    --surface-1: #101010;
    --surface-2: #1A1A1A;
    background-color: #000000;
    color: #FFD700;
  }
  body.theme-yellow a, body.theme-yellow button {
    color: #FFD700 !important;
  }

  body.theme-solar {
    --bg-void: #F8FAFC;
    --surface-1: #FFFFFF;
    --surface-2: #F1F5F9;
    background-color: #F8FAFC;
    color: #0F172A;
  }
  body.theme-solar .text-slate-100, body.theme-solar .text-white {
    color: #0F172A !important;
  }
  body.theme-solar .text-slate-400 {
    color: #475569 !important;
  }
  body.theme-solar .bg-void {
    background-color: #F8FAFC !important;
  }
  body.theme-solar .bg-surface-1 {
    background-color: #FFFFFF !important;
  }
  body.theme-solar .bg-surface-2 {
    background-color: #F1F5F9 !important;
  }
  body.theme-solar .border-border-subtle {
    border-color: #CBD5E1 !important;
  }

  body.theme-cream {
    --bg-void: #FBF7EE;
    --surface-1: #F5EEDB;
    --surface-2: #ECE2C8;
    background-color: #FBF7EE;
    color: #2D2B28;
  }
  body.theme-cream .text-slate-100, body.theme-cream .text-white {
    color: #2D2B28 !important;
  }
  body.theme-cream .text-slate-400 {
    color: #5C5850 !important;
  }
  body.theme-cream .bg-void {
    background-color: #FBF7EE !important;
  }
  body.theme-cream .bg-surface-1 {
    background-color: #F5EEDB !important;
  }
  body.theme-cream .bg-surface-2 {
    background-color: #ECE2C8 !important;
  }
  body.theme-cream .border-border-subtle {
    border-color: #DDD2B8 !important;
  }

  /* Dyslexia Friendly Font Modes */
  body.font-atkinson {
    font-family: 'Atkinson Hyperlegible', sans-serif !important;
    letter-spacing: 0.02em;
    word-spacing: 0.05em;
  }
  body.font-lexend {
    font-family: 'Lexend', sans-serif !important;
    letter-spacing: 0.015em;
  }
  body.font-mono {
    font-family: 'JetBrains Mono', monospace !important;
  }

  /* Focus ring contract */
  *:focus-visible {
    outline: 2px solid #10B981 !important;
    outline-offset: 2px !important;
  }
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: #070A0F;
}
::-webkit-scrollbar-thumb {
  background: #1E2C44;
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: #334A6E;
}

/* Screen Reader Skip Link */
.skip-link {
  position: absolute;
  top: -40px;
  left: 12px;
  background: #10B981;
  color: #070A0F;
  padding: 8px 16px;
  z-index: 100;
  font-weight: 700;
  border-radius: 4px;
  transition: top 0.2s ease;
}
.skip-link:focus {
  top: 12px;
}

import React, { createContext, useContext, useState, useEffect, useCallback } from "react";

export type A11yTheme = "obsidian" | "oled" | "yellow" | "solar" | "cream";
export type A11yFont = "sans" | "atkinson" | "lexend" | "mono";
export type A11yLineHeight = "normal" | "relaxed" | "loose";
export type A11yLetterSpacing = "normal" | "wide" | "wider";

interface AccessibilityContextType {
  fontSize: number;
  setFontSize: (size: number) => void;
  fontFamily: A11yFont;
  setFontFamily: (font: A11yFont) => void;
  theme: A11yTheme;
  setTheme: (theme: A11yTheme) => void;
  lineHeight: A11yLineHeight;
  setLineHeight: (lh: A11yLineHeight) => void;
  letterSpacing: A11yLetterSpacing;
  setLetterSpacing: (ls: A11yLetterSpacing) => void;
  readingRuler: boolean;
  setReadingRuler: (active: boolean) => void;
  speechRate: number;
  setSpeechRate: (rate: number) => void;
  isSpeaking: boolean;
  speak: (text: string) => void;
  stopSpeech: () => void;
  a11yDrawerOpen: boolean;
  setA11yDrawerOpen: (open: boolean) => void;
  shortcutsOpen: boolean;
  setShortcutsOpen: (open: boolean) => void;
  resetDefaults: () => void;
}

const AccessibilityContext = createContext<AccessibilityContextType | undefined>(undefined);

export const AccessibilityProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [fontSize, setFontSize] = useState<number>(() => {
    return parseInt(localStorage.getItem("boundless_a11y_font_size") || "100", 10);
  });
  const [fontFamily, setFontFamily] = useState<A11yFont>(() => {
    return (localStorage.getItem("boundless_a11y_font") as A11yFont) || "sans";
  });
  const [theme, setTheme] = useState<A11yTheme>(() => {
    return (localStorage.getItem("boundless_a11y_theme") as A11yTheme) || "obsidian";
  });
  const [lineHeight, setLineHeight] = useState<A11yLineHeight>(() => {
    return (localStorage.getItem("boundless_a11y_line_height") as A11yLineHeight) || "normal";
  });
  const [letterSpacing, setLetterSpacing] = useState<A11yLetterSpacing>(() => {
    return (localStorage.getItem("boundless_a11y_letter_spacing") as A11yLetterSpacing) || "normal";
  });
  const [readingRuler, setReadingRuler] = useState<boolean>(false);
  const [speechRate, setSpeechRate] = useState<number>(1.0);
  const [isSpeaking, setIsSpeaking] = useState<boolean>(false);
  const [a11yDrawerOpen, setA11yDrawerOpen] = useState<boolean>(false);
  const [shortcutsOpen, setShortcutsOpen] = useState<boolean>(false);

  // Apply theme to document body
  useEffect(() => {
    const body = document.body;
    body.classList.remove("theme-obsidian", "theme-oled", "theme-yellow", "theme-solar", "theme-cream");
    body.classList.add(`theme-${theme}`);
    localStorage.setItem("boundless_a11y_theme", theme);
  }, [theme]);

  // Apply font family
  useEffect(() => {
    const body = document.body;
    body.classList.remove("font-sans", "font-atkinson", "font-lexend", "font-mono");
    body.classList.add(`font-${fontFamily}`);
    localStorage.setItem("boundless_a11y_font", fontFamily);
  }, [fontFamily]);

  // Apply root font size scaling
  useEffect(() => {
    document.documentElement.style.fontSize = `${fontSize}%`;
    localStorage.setItem("boundless_a11y_font_size", fontSize.toString());
  }, [fontSize]);

  // Apply line height and letter spacing
  useEffect(() => {
    localStorage.setItem("boundless_a11y_line_height", lineHeight);
    localStorage.setItem("boundless_a11y_letter_spacing", letterSpacing);
  }, [lineHeight, letterSpacing]);

  // Web Speech API
  const speak = useCallback((text: string) => {
    if (!("speechSynthesis" in window)) return;
    window.speechSynthesis.cancel();
    const cleanText = text.replace(/<[^>]*>/g, " ").trim();
    if (!cleanText) return;
    const utterance = new SpeechSynthesisUtterance(cleanText);
    utterance.rate = speechRate;
    utterance.onstart = () => setIsSpeaking(true);
    utterance.onend = () => setIsSpeaking(false);
    utterance.onerror = () => setIsSpeaking(false);
    window.speechSynthesis.speak(utterance);
  }, [speechRate]);

  const stopSpeech = useCallback(() => {
    if (!("speechSynthesis" in window)) return;
    window.speechSynthesis.cancel();
    setIsSpeaking(false);
  }, []);

  const resetDefaults = useCallback(() => {
    setFontSize(100);
    setFontFamily("sans");
    setTheme("obsidian");
    setLineHeight("normal");
    setLetterSpacing("normal");
    setReadingRuler(false);
    setSpeechRate(1.0);
    stopSpeech();
  }, [stopSpeech]);

  // Keyboard shortcut handler
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ignore if in input or textarea
      if (["INPUT", "TEXTAREA", "SELECT"].includes((e.target as HTMLElement)?.tagName)) {
        return;
      }
      if (e.key === "?" && !e.ctrlKey && !e.metaKey) {
        e.preventDefault();
        setShortcutsOpen((prev) => !prev);
      } else if (e.altKey && (e.key === "a" || e.key === "A")) {
        e.preventDefault();
        setA11yDrawerOpen((prev) => !prev);
      } else if (e.key === "Escape") {
        setA11yDrawerOpen(false);
        setShortcutsOpen(false);
        stopSpeech();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [stopSpeech]);

  return (
    <AccessibilityContext.Provider
      value={{
        fontSize,
        setFontSize,
        fontFamily,
        setFontFamily,
        theme,
        setTheme,
        lineHeight,
        setLineHeight,
        letterSpacing,
        setLetterSpacing,
        readingRuler,
        setReadingRuler,
        speechRate,
        setSpeechRate,
        isSpeaking,
        speak,
        stopSpeech,
        a11yDrawerOpen,
        setA11yDrawerOpen,
        shortcutsOpen,
        setShortcutsOpen,
        resetDefaults,
      }}
    >
      {children}
    </AccessibilityContext.Provider>
  );
};

export const useAccessibility = () => {
  const context = useContext(AccessibilityContext);
  if (!context) {
    throw new Error("useAccessibility must be used within an AccessibilityProvider");
  }
  return context;
};

import React, { createContext, useContext, useState, useEffect, useCallback } from "react";

export interface SystemStatus {
  status: string;
  port: number;
  boundless_port?: number;
  processing_dir: string;
  profiles_dir: string;
  inbox: number;
  active: number;
  done: number;
  failed: number;
  profiles: number;
  watcher: {
    active: boolean;
    inbox_dir: string;
    interval_sec: number;
  };
  system: {
    has_lxml: boolean;
    has_pymupdf: boolean;
    has_ebooklib: boolean;
    has_docx: boolean;
    hot_reload: boolean;
  };
}

export interface InboxItem {
  filename: string;
  size: number;
  modified_at: string;
  title: string;
  format: "epub" | "pdf" | "docx" | "doc" | "other";
  upload_id?: string;
  profile?: any;
}

export interface ChunkInfo {
  filename: string;
  size: number;
  path: string;
  title?: string;
  chapters?: string[];
  reading_time_mins?: number;
  accessibility_score?: number;
}

export interface Job {
  id: string;
  filename: string;
  status: "pending" | "processing" | "completed" | "failed";
  progress: number;
  stage: string;
  created_at: string;
  completed_at: string | null;
  chunks_count: number;
  chunks: ChunkInfo[];
  error: string | null;
  profile_summary?: {
    publisher?: string;
    pipeline?: string;
    spine_items?: number;
    has_mathml?: boolean;
    a11y_features?: string[];
  };
  logs: string[];
}

export interface Settings {
  auto_watch_inbox: boolean;
  auto_profile_on_upload: boolean;
  auto_split_on_upload: boolean;
  default_max_size_mb: number;
  max_size_mb_options: number[];
  natural_reader_limit_mb: number;
  default_split_method: "size" | "toc";
  scan_recursive: boolean;
  scan_extensions: string[];
  theme: string;
}

export interface PublisherProfile {
  name: string;
  filename: string;
  publisher: string;
  pipeline: string;
  size_mb: number;
  spine_items: number;
  scripted_items: number;
  s9ml_chunks: number;
  has_mathml: boolean;
  accessibility_features: string[];
  description: string;
}

export interface EdgeCase {
  id: string;
  title: string;
  category: "EPUB Packaging" | "PDF Structural" | "DOCX Semantics" | "Accessibility & ADA" | "TTS & Natural Reader";
  severity: "Critical" | "Major" | "Minor" | "Info";
  format: string;
  description: string;
  mitigation: string;
  legal_ref: string;
}

interface BoundlessContextType {
  status: SystemStatus | null;
  inbox: InboxItem[];
  jobs: Job[];
  profiles: PublisherProfile[];
  edgeCases: EdgeCase[];
  settings: Settings;
  activeJob: Job | null;
  setActiveJob: (job: Job | null) => void;
  terminalLogs: string[];
  addTerminalLog: (log: string) => void;
  clearTerminalLogs: () => void;
  isLoading: boolean;
  refreshAll: () => Promise<void>;
  uploadFiles: (files: FileList | File[], maxMb?: number, method?: "size" | "toc") => Promise<void>;
  processFile: (filename: string) => Promise<void>;
  processAll: () => Promise<void>;
  scanDirectory: (path?: string) => Promise<number>;
  deleteInboxItem: (filename: string) => Promise<void>;
  deleteJobRecord: (jobId: string) => Promise<void>;
  retryJobRecord: (jobId: string) => Promise<void>;
  updateSettings: (newSettings: Partial<Settings>) => Promise<void>;
}

const DEFAULT_SETTINGS_STATE: Settings = {
  auto_watch_inbox: true,
  auto_profile_on_upload: true,
  auto_split_on_upload: false,
  default_max_size_mb: 50,
  max_size_mb_options: [25, 50, 75, 100],
  natural_reader_limit_mb: 50,
  default_split_method: "size",
  scan_recursive: false,
  scan_extensions: ["epub", "pdf", "docx", "doc"],
  theme: "dark",
};

// Curated comprehensive 200 Edge Cases representative sample
const SEED_EDGE_CASES: EdgeCase[] = [
  {
    id: "EDGE-001",
    title: "50MB Natural Reader Buffer Overflow",
    category: "TTS & Natural Reader",
    severity: "Critical",
    format: "EPUB 3 / PDF",
    description: "TTS engines crash or stutter with unhandled memory allocation errors when parsing continuous files >50MB.",
    mitigation: "Strict slice boundary enforcement at <= 50MB ceiling while preserving chapter semantics.",
    legal_ref: "ADA Title II §35.160",
  },
  {
    id: "EDGE-002",
    title: "McGraw-Hill s9ml Chunked Markup Cleaving",
    category: "EPUB Packaging",
    severity: "Critical",
    format: "EPUB 3 (MHE Acme)",
    description: "MHE Acme / PublishOne SmartBook uses deeply nested s9ml tags that cause DOM corruption when split across arbitrary byte bounds.",
    mitigation: "DOM balance inspector traces open XML nodes and synthesizes balanced closing and reopening tags on chunk boundaries.",
    legal_ref: "WCAG 2.2 4.1.1 Parsing",
  },
  {
    id: "EDGE-003",
    title: "Skipped Heading Hierarchy (H1 -> H4)",
    category: "Accessibility & ADA",
    severity: "Major",
    format: "All Formats",
    description: "Headings jump directly from document title H1 to subsection H4, disorienting screen reader navigation.",
    mitigation: "Auto-promotes skipped heading ranks or injects aria-level attributes to restore logical tree.",
    legal_ref: "Section 508 §504 (WCAG 2.4.6)",
  },
  {
    id: "EDGE-004",
    title: "Missing NCX in EPUB 3 Legacy Fallback",
    category: "EPUB Packaging",
    severity: "Major",
    format: "EPUB 3.0",
    description: "EPUB 3 documents relying solely on nav.xhtml fail on older DAISY hardware and legacy Kurzweil readers needing toc.ncx.",
    mitigation: "Auto-generates conforming toc.ncx alongside nav.xhtml across all generated chunk archives.",
    legal_ref: "Section 508 §1194.22",
  },
  {
    id: "EDGE-005",
    title: "Encrypted PDF Outline and Stripped Bookmarks",
    category: "PDF Structural",
    severity: "Critical",
    format: "PDF",
    description: "Publisher security settings strip standard bookmark trees, preventing TOC-guided assistive navigation.",
    mitigation: "Geometry and font-size heuristic engine analyzes layout typography to construct a virtual bookmark outline.",
    legal_ref: "ADA Title II §35.149",
  },
  {
    id: "EDGE-006",
    title: "MathML Equations Without Spoken Audio Fallback",
    category: "Accessibility & ADA",
    severity: "Critical",
    format: "EPUB 3 / DOCX",
    description: "Assistive speech synthesizers fail to pronounce raw MathML tags without alt text or TeX speech annotations.",
    mitigation: "Injects TeX annotation and generates natural language speech synthesis hints for mathematical formulas.",
