            <div className="flex items-center justify-between">
              <div className="flex items-center gap-1.5 text-sm font-semibold text-slate-200">
                <Volume2 className="h-4 w-4 text-emerald-400" />
                <span>Screen Speech Engine</span>
              </div>
              <button
                onClick={() => {
                  if (isSpeaking) {
                    stopSpeech();
                  } else {
                    speak("Boundless is an accessibility-first document splitter and autonomous ingestion engine.");
                  }
                }}
                className="rounded bg-emerald-600 px-2.5 py-1 text-xs font-semibold text-void hover:bg-emerald-500"
              >
                {isSpeaking ? "Stop Voice" : "Test Voice"}
              </button>
            </div>
            <div>
              <div className="flex justify-between text-xs text-slate-300">
                <span>Playback Speed</span>
                <span className="font-mono text-emerald-400">{speechRate.toFixed(2)}x</span>
              </div>
              <input
                type="range"
                min="0.5"
                max="2.5"
                step="0.1"
                value={speechRate}
                onChange={(e) => setSpeechRate(parseFloat(e.target.value))}
                className="mt-1.5 w-full accent-emerald-500"
              />
            </div>
          </div>
        </div>

        {/* Footer info */}
        <div className="mt-auto border-t border-border-subtle pt-4 text-center text-xs text-slate-400">
          Complies with Section 508 §1194.22 & WCAG 2.2 AAA
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from "react";
