export const Studio: React.FC = () => {
  const {
    inbox,
    jobs,
    uploadFiles,
    processFile,
    processAll,
    deleteInboxItem,
    deleteJobRecord,
    retryJobRecord,
    terminalLogs,
    clearTerminalLogs,
    isLoading,
    setActiveJob,
