              for autonomous background ingestion & splitting.
            </span>
            <p className="text-xs text-slate-400 mt-0.5">
              Strictly adheres to <strong>Natural Reader</strong> 50MB audio buffer limits and ADA Title II standards.
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2 self-end sm:self-center">
          <button
            onClick={processAll}
            disabled={inbox.length === 0}
            className="flex items-center gap-1 rounded-lg bg-emerald-600 px-3 py-1.5 text-xs font-semibold text-void hover:bg-emerald-500 disabled:opacity-40"
          >
            <Zap className="h-3.5 w-3.5" />
            <span>Process All ({inbox.length})</span>
          </button>
        </div>
      </div>

      {/* Main Upload / Drag & Drop Studio Zone */}
      <div
        onDragEnter={handleDrag}
        onDragOver={handleDrag}
        onDragLeave={handleDrag}
        onDrop={handleDrop}
        className={`relative overflow-hidden rounded-2xl border-2 border-dashed p-8 transition-all ${
          dragActive
            ? "border-emerald-400 bg-emerald-500/15 shadow-[0_0_40px_rgba(16,185,129,0.25)] scale-[1.005]"
            : "border-border-bright bg-surface-1/80 hover:border-emerald-500/50"
