              </div>
              <span className="text-[10px] text-slate-400">Pending</span>
            </div>

            <div id="lane-inbox" className="mt-3 space-y-2.5 flex-1 min-h-[160px] overflow-y-auto max-h-[360px] pr-1">
              {inbox.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-8 text-center text-xs text-slate-400">
                  <span className="text-xl mb-1">📭</span>
                  <span>Inbox is empty</span>
                  <span className="text-[10px] text-slate-500">Drop files into processing/inbox/</span>
