                        <span className="text-xs font-semibold text-slate-200 truncate" title={item.filename}>
                          {item.title}
                        </span>
                      </div>
                      <button
                        onClick={() => deleteInboxItem(item.filename)}
                        className="text-slate-500 hover:text-crimson-alert transition-colors"
                        title="Remove from inbox"
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </button>
                    </div>

                    <div className="mt-2 flex items-center justify-between text-[11px] text-slate-400">
                      <span>{formatFileSize(item.size)}</span>
                      <button
                        onClick={() => processFile(item.filename)}
                        className="flex items-center gap-1 rounded bg-emerald-600/80 px-2 py-1 font-semibold text-void hover:bg-emerald-500 transition-colors"
                      >
                        <Zap className="h-3 w-3" />
                        <span>Process</span>
                      </button>
                    </div>
