          </div>

          {/* Lane 2: ACTIVE */}
          <div className="flex flex-col rounded-xl border border-border-subtle bg-surface-1/90 p-4">
            <div className="flex items-center justify-between border-b border-border-subtle pb-3">
              <div className="flex items-center gap-2">
                <span className="text-base">⚙️</span>
                <span className="font-bold text-slate-100 text-sm">Active</span>
                <span id="c-active" className="rounded-full bg-cyan-500/20 px-2 py-0.5 font-mono text-xs font-bold text-cyan-400">
                  {activeJobs.length}
                </span>
              </div>
              <span className="text-[10px] text-slate-400">Processing</span>
            </div>

            <div id="lane-active" className="mt-3 space-y-2.5 flex-1 min-h-[160px] overflow-y-auto max-h-[360px] pr-1">
              {activeJobs.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-8 text-center text-xs text-slate-400">
                  <span className="text-xl mb-1">💤</span>
                  <span>No active jobs</span>
                  <span className="text-[10px] text-slate-500">Autonomous watcher standing by</span>
                </div>
              ) : (
                activeJobs.map((job) => (
                  <div
                    key={job.id}
                    className="rounded-lg border border-cyan-500/30 bg-surface-2/80 p-3 shadow-sm"
                  >
                    <div className="flex items-center justify-between text-xs font-semibold text-slate-200">
                      <span className="truncate" title={job.filename}>{job.filename}</span>
                      <span className="font-mono text-cyan-400">{job.progress}%</span>
                    </div>

                    <div className="mt-2 h-1.5 w-full overflow-hidden rounded-full bg-surface-3">
                      <div
                        className="h-full bg-gradient-to-r from-emerald-500 to-cyan-400 transition-all duration-300"
                        style={{ width: `${job.progress}%` }}
