              <div className="flex items-center gap-2">
                <span className="text-base">✅</span>
                <span className="font-bold text-slate-100 text-sm">Completed</span>
                <span id="c-done" className="rounded-full bg-emerald-500/20 px-2 py-0.5 font-mono text-xs font-bold text-emerald-400">
                  {doneJobs.length}
                </span>
              </div>
              <span className="text-[10px] text-slate-400">Ready</span>
            </div>

            <div id="lane-done" className="mt-3 space-y-2.5 flex-1 min-h-[160px] overflow-y-auto max-h-[360px] pr-1">
              {doneJobs.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-8 text-center text-xs text-slate-400">
                  <span className="text-xl mb-1">📁</span>
                  <span>No completed jobs yet</span>
