            <div id="lane-failed" className="mt-3 space-y-2.5 flex-1 min-h-[160px] overflow-y-auto max-h-[360px] pr-1">
              {failedJobs.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-8 text-center text-xs text-emerald-400/80">
                  <CheckCircle2 className="h-6 w-6 mb-1 text-emerald-400" />
                  <span>Zero pipeline errors</span>
                  <span className="text-[10px] text-slate-500">All chunks validated clean</span>
                </div>
              ) : (
                failedJobs.map((job) => (
                  <div
                    key={job.id}
                    className="rounded-lg border border-crimson-alert/40 bg-surface-2/60 p-3"
                  >
                    <div className="flex items-center justify-between text-xs font-semibold text-slate-200">
                      <span className="truncate">{job.filename}</span>
                      <span className="text-[10px] text-crimson-alert">Failed</span>
                    </div>
                    <p className="mt-1 text-[11px] text-slate-400 line-clamp-2">
                      {job.error || "Container parsing anomaly"}
                    </p>
                    <div className="mt-2 flex items-center justify-end gap-2">
                      <button
                        onClick={() => retryJobRecord(job.id)}
                        className="rounded bg-amber-600/80 px-2 py-0.5 text-xs font-semibold text-void hover:bg-amber-500"
                      >
                        Retry
                      </button>
                      <button
                        onClick={() => deleteJobRecord(job.id)}
                        className="text-slate-500 hover:text-crimson-alert"
                      >
                        <Trash2 className="h-3 w-3" />
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Collapsible Bottom Diagnostic Terminal */}
      <div className="rounded-xl border border-border-subtle bg-surface-1 shadow-lg overflow-hidden">
        <div
          onClick={() => setTerminalExpanded(!terminalExpanded)}
          className="flex cursor-pointer items-center justify-between border-b border-border-subtle bg-surface-2/80 px-4 py-2.5 select-none hover:bg-surface-2 transition-colors"
        >
          <div className="flex items-center gap-2 text-xs font-bold text-slate-200 font-mono">
            <Terminal className="h-4 w-4 text-emerald-400" />
            <span>Boundless Real-Time Ingestion Engine Terminal</span>
            <span className="rounded bg-surface-3 px-1.5 py-0.2 text-[10px] text-emerald-400">
              WAL Connected
            </span>
          </div>
          <div className="flex items-center gap-3">
            <button
              onClick={(e) => {
                e.stopPropagation();
                clearTerminalLogs();
              }}
              className="text-[11px] text-slate-400 hover:text-slate-200"
            >
              Clear Logs
            </button>
            {terminalExpanded ? <ChevronUp className="h-4 w-4 text-slate-400" /> : <ChevronDown className="h-4 w-4 text-slate-400" />}
          </div>
        </div>

        {terminalExpanded && (
          <div className="bg-void p-4 font-mono text-xs text-slate-300 max-h-48 overflow-y-auto space-y-1">
            {terminalLogs.map((log, idx) => {
              const isInfo = log.includes("[INFO]");
              const isA11y = log.includes("[A11Y]");
              const isSplit = log.includes("[SPLIT]");
              const isSuccess = log.includes("[SUCCESS]");
              const isWarn = log.includes("[WARN]");

              let color = "text-slate-400";
              if (isSuccess) color = "text-emerald-400 font-bold";
              else if (isA11y) color = "text-cyan-400";
              else if (isSplit) color = "text-emerald-300";
              else if (isWarn) color = "text-amber-400";
              else if (isInfo) color = "text-slate-200";

              return (
                <div key={idx} className={`${color} leading-relaxed`}>
                  {log}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

