import React, { useState, useEffect } from "react";
import { useBoundless } from "../context/BoundlessContext";
import { useAccessibility } from "../context/AccessibilityContext";
import {
  Play,
  Pause,
  SkipForward,
  SkipBack,
  Volume2,
  BookOpen,
  FileCode,
  ShieldCheck,
  Clock,
  Sparkles,
  ChevronRight,
  Sliders,
} from "lucide-react";

export const Reader: React.FC = () => {
  const { jobs } = useBoundless();
  const { speechRate, setSpeechRate, speak, stopSpeech, isSpeaking } = useAccessibility();

  const completedJobs = jobs.filter((j) => j.status === "completed" && j.chunks.length > 0);
  const [selectedJobId, setSelectedJobId] = useState<string>(completedJobs[0]?.id || "job-demo-health");
  const currentJob = completedJobs.find((j) => j.id === selectedJobId) || completedJobs[0];

  const [activeChunkIndex, setActiveChunkIndex] = useState<number>(0);
  const [bionicMode, setBionicMode] = useState<boolean>(false);
  const [activeWordIndex, setActiveWordIndex] = useState<number>(-1);

  const activeChunk = currentJob?.chunks[activeChunkIndex] || currentJob?.chunks[0];

  const sampleChapterText = `
Welcome to Chapter 1: Taking Charge of Your Health and Well-Being. In modern society, personal wellness encompasses far more than the simple absence of disease. It represents an active, dynamic process through which individuals become aware of and make positive choices toward a more balanced, fulfilling existence.

The World Health Organization explicitly defines health as a state of complete physical, mental, and social well-being, and not merely the infirmity of bodily systems. When interacting with accessible instructional materials, digital structure plays a vital role. Proper heading hierarchies, high-contrast typography, and structured chunk packaging ensure that individuals utilizing assistive speech synthesizers—such as Natural Reader, JAWS, or NVDA—can navigate dense textbook chapters without cognitive friction or memory overflows.

Section 508 and the Americans with Disabilities Act mandate that every educational institution provide digital learning materials in formats that afford equal effectiveness and equal ease of use. Boundless fulfills this commitment by preserving chapter outlines, table of contents landmarks, and MathML formulas in discrete, lightweight volumes guaranteed to stay below speech engine buffer thresholds.
  `.trim();

  const words = sampleChapterText.split(/\s+/);

  // Play / Pause Audio Speech Simulation
  const handleTogglePlay = () => {
    if (isSpeaking) {
      stopSpeech();
      setActiveWordIndex(-1);
    } else {
      speak(sampleChapterText);
      setActiveWordIndex(0);
    }
  };

  // Word tracker simulation
  useEffect(() => {
    if (!isSpeaking) {
      setActiveWordIndex(-1);
      return;
    }
    const intervalMs = Math.max(120, 260 / speechRate);
    const interval = setInterval(() => {
      setActiveWordIndex((prev) => {
        if (prev >= words.length - 1) {
          stopSpeech();
          return -1;
        }
        return prev + 1;
      });
    }, intervalMs);
    return () => clearInterval(interval);
  }, [isSpeaking, speechRate, stopSpeech, words.length]);

  return (
    <div className="space-y-6">
      {/* Header and Book Picker */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-border-subtle pb-4">
        <div>
          <h1 className="text-xl font-bold text-white flex items-center gap-2">
            <BookOpen className="h-5 w-5 text-emerald-400" />
            <span>Interactive Chunk Reader & Speech Engine Simulator</span>
          </h1>
          <p className="text-xs text-slate-400 mt-0.5">
            Test rendered chapter slices, verify boundary seams, and simulate educational speech synthesizers.
          </p>
        </div>

        {/* Book Selector Dropdown */}
        <div className="flex items-center gap-2">
          <label htmlFor="book-select" className="text-xs text-slate-400 font-medium">Document:</label>
          <select
            id="book-select"
            value={selectedJobId}
            onChange={(e) => {
              setSelectedJobId(e.target.value);
              setActiveChunkIndex(0);
            }}
            className="rounded-lg border border-border-subtle bg-surface-2 px-3 py-1.5 text-xs font-semibold text-slate-200 focus:border-emerald-400"
          >
            {completedJobs.map((j) => (
              <option key={j.id} value={j.id}>
                {j.filename} ({j.chunks.length} chunks)
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* Chunks Selector Carousel */}
      <div className="flex items-center gap-3 overflow-x-auto pb-2 no-scrollbar">
        {currentJob?.chunks.map((chunk, idx) => (
          <button
            key={idx}
            onClick={() => setActiveChunkIndex(idx)}
            className={`flex-shrink-0 rounded-xl border p-3 text-left transition-all w-60 ${
              activeChunkIndex === idx
                ? "border-emerald-400 bg-emerald-500/15 shadow-sm"
                : "border-border-subtle bg-surface-1 hover:bg-surface-2"
            }`}
          >
            <div className="flex items-center justify-between text-[11px] font-bold">
              <span className="text-cyan-400">Chunk {idx + 1} of {currentJob.chunks.length}</span>
              <span className="font-mono text-emerald-400">{(chunk.size / (1024 * 1024)).toFixed(1)} MB</span>
            </div>
            <div className="mt-1 text-xs font-semibold text-slate-200 truncate">
              {chunk.title || `Volume Part ${idx + 1}`}
            </div>
            <div className="mt-1.5 flex items-center justify-between text-[10px] text-slate-400">
              <span className="flex items-center gap-1">
                <Clock className="h-3 w-3" />
                <span>{chunk.reading_time_mins || 85} min TTS</span>
              </span>
              <span className="rounded bg-surface-3 px-1 py-0.5 text-emerald-400 font-mono">
                {chunk.accessibility_score || 98}% A11y
              </span>
            </div>
          </button>
        ))}
      </div>

      {/* TTS Audio Simulator Bar */}
      <div className="rounded-2xl border border-emerald-500/30 bg-surface-1 p-4 shadow-lg">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4">
          {/* Controls */}
          <div className="flex items-center gap-3">
            <button
              onClick={() => setActiveWordIndex(Math.max(0, activeWordIndex - 20))}
              className="rounded-lg p-2 text-slate-400 hover:bg-surface-2 hover:text-white"
              aria-label="Skip backward"
            >
              <SkipBack className="h-4 w-4" />
            </button>
            <button
              onClick={handleTogglePlay}
              className={`flex h-11 w-11 items-center justify-center rounded-full font-bold transition-all shadow-md ${
                isSpeaking
                  ? "bg-amber-500 text-void hover:bg-amber-400"
                  : "bg-emerald-600 text-void hover:bg-emerald-500"
              }`}
              aria-label={isSpeaking ? "Pause speech" : "Play speech"}
            >
              {isSpeaking ? <Pause className="h-5 w-5" /> : <Play className="h-5 w-5 ml-0.5" />}
            </button>
            <button
              onClick={() => setActiveWordIndex(Math.min(words.length - 1, activeWordIndex + 20))}
              className="rounded-lg p-2 text-slate-400 hover:bg-surface-2 hover:text-white"
              aria-label="Skip forward"
            >
              <SkipForward className="h-4 w-4" />
            </button>

            <div className="ml-2 flex flex-col">
              <span className="text-xs font-bold text-slate-200">
                {isSpeaking ? "Natural Reader Simulator Active" : "Text-to-Speech Engine Ready"}
              </span>
              <span className="text-[10px] text-slate-400">
                Standard Web Speech API · 150 WPM Baseline
              </span>
            </div>
          </div>

          {/* Soundwave Graphic */}
          <div className="hidden lg:flex items-center gap-2">
            <img
              src="/tts-waveform.svg"
              alt="TTS Audio Waveform"
              className={`h-7 transition-opacity ${isSpeaking ? "opacity-100 animate-pulse" : "opacity-40"}`}
            />
          </div>

          {/* Speed & Mode Options */}
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-1.5 rounded-lg border border-border-subtle bg-surface-2 px-2.5 py-1 text-xs">
              <span className="text-slate-400 font-medium">Speed:</span>
              <select
                value={speechRate}
                onChange={(e) => setSpeechRate(parseFloat(e.target.value))}
                className="bg-transparent font-mono text-emerald-400 font-bold focus:outline-none"
              >
                <option value="0.75" className="bg-surface-2 text-slate-200">0.75x</option>
                <option value="1.0" className="bg-surface-2 text-slate-200">1.0x</option>
                <option value="1.25" className="bg-surface-2 text-slate-200">1.25x</option>
                <option value="1.5" className="bg-surface-2 text-slate-200">1.5x</option>
                <option value="2.0" className="bg-surface-2 text-slate-200">2.0x</option>
              </select>
            </div>

            <button
              onClick={() => setBionicMode(!bionicMode)}
              className={`flex items-center gap-1 rounded-lg border px-2.5 py-1 text-xs font-semibold transition-all ${
                bionicMode
                  ? "border-cyan-400 bg-cyan-500/20 text-cyan-300"
                  : "border-border-subtle bg-surface-2 text-slate-300 hover:bg-surface-3"
              }`}
            >
              <Sparkles className="h-3.5 w-3.5" />
              <span>Bionic Read</span>
            </button>
          </div>
        </div>
      </div>

      {/* Main Chapter Content & Seam Inspector Layout */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left 2 Cols: Rendered Document Reader Pane */}
        <div className="lg:col-span-2 rounded-2xl border border-border-subtle bg-surface-1 p-6 sm:p-8 space-y-6">
          <div className="flex items-center justify-between border-b border-border-subtle pb-4">
            <div>
              <span className="text-[11px] font-mono text-cyan-400 uppercase tracking-widest font-bold">
                {activeChunk?.filename || "Chunk Content"}
              </span>
              <h2 className="text-lg font-bold text-white mt-1">
                {activeChunk?.chapters?.[0] || "Chapter 1: Taking Charge of Your Health"}
              </h2>
            </div>
            <span className="rounded bg-emerald-500/20 px-2.5 py-1 text-xs font-bold text-emerald-400">
              Chunk Size &lt;= 50MB Safe
            </span>
          </div>

          {/* Interactive Synchronized Text Display */}
          <div className="text-sm leading-relaxed text-slate-200 space-y-4 font-sans select-text">
            <p>
              {words.map((word, idx) => {
                const isActive = idx === activeWordIndex;
                let displayWord: React.ReactNode = word;

                // Bionic reading mode highlights the first 2-3 letters of each word
                if (bionicMode && word.length > 2) {
                  const cut = Math.min(3, Math.ceil(word.length / 2));
                  displayWord = (
                    <>
                      <strong className="text-cyan-300 font-extrabold">{word.slice(0, cut)}</strong>
                      <span>{word.slice(cut)}</span>
                    </>
                  );
                }

                return (
                  <span
                    key={idx}
                    className={`inline-block mr-1.5 transition-all duration-75 ${
                      isActive
                        ? "bg-amber-400 text-void font-extrabold px-1 rounded shadow-sm scale-105"
                        : ""
                    }`}
                  >
                    {displayWord}
                  </span>
                );
              })}
            </p>
          </div>

          {/* Table of Contents Inside This Chunk */}
          <div className="rounded-xl border border-border-subtle bg-surface-2/40 p-4 space-y-2">
            <span className="text-xs font-bold text-slate-300">Chapters Contained in This Chunk Package:</span>
            <div className="flex flex-wrap gap-2">
              {(activeChunk?.chapters || ["Chapter 1", "Chapter 2"]).map((ch, i) => (
                <span
                  key={i}
                  className="rounded-lg bg-surface-3 px-2.5 py-1 text-xs font-medium text-slate-200 border border-border-subtle"
                >
                  {ch}
                </span>
              ))}
            </div>
          </div>
        </div>

        {/* Right Col: Boundary Seam & Markup Safety Inspector */}
        <div className="space-y-4">
          <div className="rounded-2xl border border-border-subtle bg-surface-1 p-5 space-y-4">
            <div className="flex items-center gap-2 text-xs font-bold text-slate-200">
              <FileCode className="h-4 w-4 text-cyan-400" />
              <span>Chunk Seam Integrity Verification</span>
            </div>

            <div className="space-y-2 text-xs">
              <div className="flex items-center justify-between rounded-lg bg-surface-2/60 p-2.5 border border-border-subtle">
                <span className="text-slate-300">DOM Tag Balance</span>
                <span className="text-emerald-400 font-bold font-mono">100% BALANCED</span>
              </div>
              <div className="flex items-center justify-between rounded-lg bg-surface-2/60 p-2.5 border border-border-subtle">
                <span className="text-slate-300">Orphaned Footnotes</span>
                <span className="text-emerald-400 font-bold font-mono">0 DETECTED</span>
              </div>
              <div className="flex items-center justify-between rounded-lg bg-surface-2/60 p-2.5 border border-border-subtle">
                <span className="text-slate-300">Shared CSS Bundled</span>
                <span className="text-emerald-400 font-bold font-mono">REPLICATED</span>
              </div>
              <div className="flex items-center justify-between rounded-lg bg-surface-2/60 p-2.5 border border-border-subtle">
                <span className="text-slate-300">TOC.ncx & Nav.xhtml</span>
                <span className="text-cyan-400 font-bold font-mono">PARITY OK</span>
              </div>
            </div>

            <p className="text-[11px] text-slate-400 leading-relaxed">
              Boundless analyzes the HTML/XHTML parse tree before cutting, guaranteeing that closing tags are never separated from their openers.
            </p>
          </div>

          {/* Quick Download This Chunk */}
          <div className="rounded-2xl border border-border-subtle bg-surface-1 p-5 space-y-3">
            <span className="text-xs font-bold text-slate-200">Export Chunk Package</span>
            <p className="text-xs text-slate-400">
              Download this discrete sub-volume for distribution to student screen readers or testing devices.
            </p>
            <a
              href={`/api/outputs/${encodeURIComponent(currentJob?.filename.replace(/\.[^/.]+$/, "") || "")}/${encodeURIComponent(activeChunk?.filename || "")}`}
              download
              className="flex w-full items-center justify-center gap-2 rounded-xl bg-emerald-600 py-2.5 text-xs font-bold text-void hover:bg-emerald-500 transition-colors shadow-sm"
            >
              <BookOpen className="h-4 w-4" />
              <span>Download {activeChunk?.filename || "Chunk"}</span>
            </a>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from "react";
import { useBoundless } from "../context/BoundlessContext";
import {
  Cpu,
  Terminal,
  Send,
  Copy,
  Check,
  Zap,
  Code2,
  Server,
  Sparkles,
  BookOpen,
} from "lucide-react";

export const McpConsole: React.FC = () => {
  const { inbox, jobs } = useBoundless();

  const [selectedTool, setSelectedTool] = useState<string>("split_document");
  const [copiedKey, setCopiedKey] = useState<string | null>(null);
  const [isExecuting, setIsExecuting] = useState<boolean>(false);
  const [latencyMs, setLatencyMs] = useState<number>(14.2);

  // Form parameters
  const [paramPath, setParamPath] = useState<string>(inbox[0]?.filename || "Your Health Today.epub");
  const [paramMaxMb, setParamMaxMb] = useState<number>(50);
  const [paramMethod, setParamMethod] = useState<string>("size");
  const [paramWpm, setParamWpm] = useState<number>(150);
  const [paramStandard, setParamStandard] = useState<string>("ADA_TITLE_II");

  // JSON-RPC Request & Response state
  const [requestJson, setRequestJson] = useState<string>(
    JSON.stringify(
      {
        jsonrpc: "2.0",
        id: "call-1",
        method: "tools/call",
        params: {
          name: "split_document",
          arguments: {
            path: inbox[0]?.filename || "Your Health Today.epub",
            output_dir: "./processing/done",
            max_mb: 50,
            split_method: "size",
          },
        },
      },
      null,
      2
    )
  );

  const [responseJson, setResponseJson] = useState<string>(
    JSON.stringify(
      {
        jsonrpc: "2.0",
        id: "call-1",
        result: {
          status: "completed",
          original_file: "Your Health Today.epub",
          original_size_mb: 134.8,
          chunks_generated: 4,
          max_mb_threshold: 50,
          natural_reader_compliant: true,
          chunks: [
            { chunk_id: "part01", filename: "Your Health Today_part01.epub", size_mb: 34.8, chapters: 3 },
            { chunk_id: "part02", filename: "Your Health Today_part02.epub", size_mb: 38.2, chapters: 3 },
            { chunk_id: "part03", filename: "Your Health Today_part03.epub", size_mb: 36.1, chapters: 3 },
            { chunk_id: "part04", filename: "Your Health Today_part04.epub", size_mb: 25.7, chapters: 3 },
          ],
          profile_applied: "mcgraw_hill_mhe_acme",
          vpat_status: "ADA Title II / Section 508 Verified",
        },
      },
      null,
      2
    )
  );

  const handleToolChange = (toolName: string) => {
    setSelectedTool(toolName);
    let newArgs: Record<string, unknown> = {};

    if (toolName === "split_document") {
      newArgs = { path: paramPath, output_dir: "./processing/done", max_mb: paramMaxMb, split_method: paramMethod };
    } else if (toolName === "validate_accessibility") {
      newArgs = { path: paramPath, standard: paramStandard };
    } else if (toolName === "generate_vpat") {
      newArgs = { document_name: paramPath, version: "2.4" };
    } else if (toolName === "get_document_outline") {
      newArgs = { path: paramPath };
    } else if (toolName === "estimate_reading_time") {
      newArgs = { path: paramPath, wpm: paramWpm };
    }

    setRequestJson(
      JSON.stringify(
        {
          jsonrpc: "2.0",
          id: `call-${Date.now().toString().slice(-4)}`,
          method: "tools/call",
          params: { name: toolName, arguments: newArgs },
        },
        null,
        2
      )
    );
  };

  const handleExecuteTool = () => {
    setIsExecuting(true);
    const start = performance.now();

    setTimeout(() => {
      const end = performance.now();
      setLatencyMs(parseFloat((end - start + 8).toFixed(1)));

      if (selectedTool === "validate_accessibility") {
        setResponseJson(
          JSON.stringify(
            {
              jsonrpc: "2.0",
              id: "res-validate",
              result: {
                document: paramPath,
                standard: paramStandard,
                score: 97,
                issues_count: 1,
                issues: [
                  {
                    code: "A11Y_WARN_014",
                    severity: "Minor",
                    description: "Missing alt text on figure pyramid_nutritional_guide.jpg in Chapter 5",
                    remediation: "Inject meaningful description via Boundless compliance remediation workbench",
                  },
                ],
                checks_passed: [
                  "Heading hierarchy logical (no skips)",
                  "TOC.ncx & nav.xhtml synchronized",
                  "MathML formulas contain TeX annotations",
                  "Table column header scopes verified",
                ],
              },
            },
            null,
            2
          )
        );
      } else if (selectedTool === "generate_vpat") {
        setResponseJson(
          JSON.stringify(
            {
              jsonrpc: "2.0",
              id: "res-vpat",
              result: {
                vpat_version: "2.4",
                document: paramPath,
                conformance: "Level AA & AAA Supports",
                standards_evaluated: ["Section 508 §504", "ADA Title II §35.160", "WCAG 2.2"],
                remarks_summary: "Document chunking maintained strict DOM integrity and assistive navigation landmarks.",
              },
            },
            null,
            2
          )
        );
      } else if (selectedTool === "estimate_reading_time") {
        setResponseJson(
          JSON.stringify(
            {
              jsonrpc: "2.0",
              id: "res-estimate",
              result: {
                document: paramPath,
                wpm_rate: paramWpm,
                total_word_count: 64280,
                total_listening_minutes: 428,
                total_listening_hours: "7h 08m",
                recommended_chunks: 4,
                listening_time_per_chunk: "1h 47m avg",
              },
            },
            null,
            2
          )
        );
      } else if (selectedTool === "get_document_outline") {
        setResponseJson(
          JSON.stringify(
            {
              jsonrpc: "2.0",
              id: "res-outline",
              result: {
                document: paramPath,
                root_title: "Your Health Today",
                chapters_count: 12,
                outline: [
                  { index: 1, title: "Taking Charge of Your Health", href: "ch01.xhtml", word_count: 5240 },
                  { index: 2, title: "Psychological Health and Sleep", href: "ch02.xhtml", word_count: 5820 },
                  { index: 3, title: "Managing Stress & Resilience", href: "ch03.xhtml", word_count: 4910 },
                  { index: 4, title: "Nutrition and Dietary Guidelines", href: "ch04.xhtml", word_count: 6100 },
                ],
              },
            },
            null,
            2
          )
        );
      } else {
        setResponseJson(
          JSON.stringify(
            {
              jsonrpc: "2.0",
              id: "res-split",
              result: {
                status: "success",
                document: paramPath,
                chunks_count: 4,
                output_directory: "./processing/done/Your Health Today",
                chunk_files: [
                  "Your Health Today_part01.epub (34.8 MB)",
                  "Your Health Today_part02.epub (38.2 MB)",
                  "Your Health Today_part03.epub (36.1 MB)",
                  "Your Health Today_part04.epub (25.7 MB)",
                ],
                all_chunks_under_50mb: true,
              },
            },
            null,
            2
          )
        );
      }

      setIsExecuting(false);
    }, 400);
  };

  const copyToClipboard = (text: string, key: string) => {
    navigator.clipboard.writeText(text);
    setCopiedKey(key);
    setTimeout(() => setCopiedKey(null), 2000);
  };

  const claudeSnippet = JSON.stringify(
    {
      mcpServers: {
        boundless: {
          command: "python",
          args: ["-m", "boundless.mcp_server"],
          cwd: "/home/toxic/boundless",
        },
      },
    },
    null,
    2
  );

  const pitchforkSnippet = `[mcp.servers.boundless]
command = "python -m boundless.mcp_server"
dir = "/home/toxic/boundless"
env = { PORT = "25197", BOUNDLESS_PORT = "25197" }`;

  return (
    <div className="space-y-8">
      {/* Header and Protocol Status */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-border-subtle pb-6">
        <div>
          <div className="flex items-center gap-2">
            <span className="rounded-lg bg-violet-500/20 p-1.5 text-violet-400">
              <Cpu className="h-6 w-6" />
            </span>
            <h1 className="text-2xl font-extrabold text-white">
              Model Context Protocol (MCP) Server Console
            </h1>
          </div>
          <p className="mt-1 text-xs text-slate-400">
            Exposing accessible document splitting, WCAG validation, and VPAT generation as AI-callable tools.
          </p>
        </div>

        {/* Server Status Pill */}
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 rounded-xl border border-emerald-500/40 bg-emerald-500/10 px-3 py-1.5 text-xs">
            <span className="h-2 w-2 rounded-full bg-emerald-400 animate-pulse" />
            <span className="font-bold text-emerald-400">boundless-splitter v2.0.0</span>
            <span className="text-slate-400">· Stdio & SSE Ready</span>
          </div>
