    elif ext == ".epub":
        try:
            from .toc_parse import parse_epub3_toc, parse_ncx_toc
            nodes = parse_epub3_toc(path) or parse_ncx_toc(path)
            outline = [{"title": n.title, "href": n.href, "play_order": n.play_order} for n in (nodes or [])]
        except Exception as e:
            outline = [{"title": "Default Outline", "note": str(e)}]
    return json.dumps({"path": path, "outline": outline}, indent=2)


@mcp.tool()
def estimate_reading_time(path: str, wpm: int = 150) -> str:
    """Estimate word count and Text-to-Speech listening duration for educational chunking."""
    if not os.path.exists(path):
        return json.dumps({"error": f"File not found: {path}"}, indent=2)
    size_mb = os.path.getsize(path) / (1024 * 1024)
    est_words = int(max(1000, size_mb * 1800))
    minutes = int(est_words / max(50, wpm))
    return json.dumps({
        "path": path,
        "size_mb": round(size_mb, 2),
        "target_wpm": wpm,
        "estimated_word_count": est_words,
        "estimated_listening_minutes": minutes,
        "recommended_chunks": max(1, int(size_mb / 45) + 1),
    }, indent=2)

@mcp.resource("docs://legal-framework")
def legal_framework() -> str:
    """ADA, IDEA, Section 508, and state accessibility law summary."""
    lines = ["# Accessibility Legal Framework", ""]
    for key, desc in A11Y_STANDARDS.items():
        lines.append(f"## {key}")
        lines.append(str(desc))
        lines.append("")
    return "\n".join(lines)


@mcp.resource("docs://edge-cases")
def edge_cases_resource() -> str:
    """Comprehensive edge case list for EPUB, PDF, DOCX processing."""
    return "\n".join(EdgeCaseRegistry.all_cases())


def main(argv=None) -> int:
    """boundless-mcp — run the MCP server over stdio."""
    ap = argparse.ArgumentParser(prog="boundless-mcp", description="Boundless MCP server (stdio)")
    ap.parse_args(argv)
    mcp.run()
    return 0


if __name__ == "__main__":
    sys.exit(main())

