    if v.startswith(_SECRET_PREFIXES) and len(v) >= 20:
        return True
    return (len(v) >= 32
            and re.fullmatch(r"[A-Za-z0-9_\-+=.]+", v) is not None
            and not any(c in v for c in "/: \t\n"))

